pub fn calculate_rsa_socle_majore(
    parameters: &Parameters,
    period: NaiveDate,
    profile: &Profile,
) -> f64 {
    let eligib = calculate_rsa_majore_eligibilite(parameters, period, profile);
    let nbenf = calculate_rsa_nb_enfants(parameters, period, profile);

    let rsa = parameters.get_scalar("prestations_sociales/solidarite_insertion/minima_sociaux/rsa").unwrap_or(0.0);
    let taux = rsa.rsa_maj.majoration_isolement_en_base_rsa.femmes_enceintes + rsa.rsa_maj.majoration_isolement_en_base_rsa.par_enfant_a_charge * nbenf;
    let socle = rsa.rsa_m.montant_de_base_du_rsa;

    return eligib * socle * taux;
}

