#[allow(dead_code, unused_variables)]
pub fn calculate_bourse_criteres_sociaux_points_de_charge_charges_familiale(
    parameters: &Parameters,
    period: NaiveDate,
    profile: &Profile,
) -> f64 {
    let nb_enf = individu.calculate_bourse_criteres_sociaux_nombre_enfants_a_charge(parameters, period, profile);
    let nb_enf_ens_sup = individu.calculate_bourse_criteres_sociaux_nombre_enfants_a_charge_dans_enseignement_superieur(parameters, period, profile);

    let nb_enf_hors_ens_sup = nb_enf - nb_enf_ens_sup;
    let nb_autre_enf_ens_sup = nb_enf_ens_sup - 1;

    let pts = parameters.get_scalar("prestations_sociales/education/bourses/enseignement_superieur/criteres_sociaux/points_de_charge/charges_familiales").unwrap_or(0.0);
    let pts_enf = (nb_enf_hors_ens_sup > 0) * nb_enf_hors_ens_sup * pts.par_enfant_a_charge;
    let pts_ens_sup = (nb_autre_enf_ens_sup > 0) * nb_autre_enf_ens_sup * pts.par_enfant_etudiant;
    return pts_enf + pts_ens_sup;
}

