#[allow(dead_code, unused_variables)]
pub fn calculate_aide_logement_montant_brut_crds(
    parameters: &Parameters,
    period: NaiveDate,
    profile: &Profile,
) -> f64 {
    let rls = parameters.get_scalar("prestations_sociales/aides_logement/reduction_loyer_solidarite").unwrap_or(0.0);
    let aide_logement_montant_brut = calculate_aide_logement_montant_brut(parameters, period, profile);
    let reduction_loyer_solidarite = calculate_reduction_loyer_solidarite(parameters, period, profile);

    let taux_rls = rls.fraction_baisse_aide_logement;
    let rls_apl = reduction_loyer_solidarite * taux_rls;

    return (0.0_f64).max((aide_logement_montant_brut - rls_apl));
}

#[allow(dead_code, unused_variables)]
pub fn calculate_aide_logement_montant(
    parameters: &Parameters,
    period: NaiveDate,
    profile: &Profile,
) -> f64 {
    let aide_logement_montant_brut = calculate_aide_logement_montant_brut_crds(parameters, period, profile);
    let crds_logement = calculate_crds_logement(parameters, period, profile);
    let montant = ((aide_logement_montant_brut + crds_logement) * 100.0_f64).round() / 100.0_f64;

    return montant;
}

